//! Provider 出网时的函数名编解码。

use std::collections::HashMap;

/// Converts a Core tool id to a name accepted by OpenAI Chat Completions.
pub fn to_wire_tool_name(name: &str) -> String {
    name.chars()
        .map(|character| match character {
            '.' | ':' => '_',
            character => character,
        })
        .collect()
}

/// Builds a wire-name to original Core-id mapping.
///
/// Multiple Core ids may encode to the same wire name, so collisions are
/// rejected instead of silently replacing an earlier entry.
pub fn mappings(names: &[&str]) -> Result<HashMap<String, String>, String> {
    let mut from_wire = HashMap::new();
    for original in names {
        let wire_name = to_wire_tool_name(original);
        if let Some(previous) = from_wire.insert(wire_name.clone(), (*original).to_string()) {
            if previous != *original {
                return Err(format!(
                    "tool name collision: {previous:?} and {original:?} both map to {wire_name:?}"
                ));
            }
        }
    }
    Ok(from_wire)
}

#[cfg(test)]
mod tests {
    use super::{mappings, to_wire_tool_name};

    #[test]
    fn replaces_openai_invalid_core_separators() {
        assert_eq!(to_wire_tool_name("fs.list"), "fs_list");
        assert_eq!(to_wire_tool_name("mcp:tool"), "mcp_tool");
    }

    #[test]
    fn preserves_names_that_are_already_legal() {
        assert_eq!(to_wire_tool_name("get_time"), "get_time");
    }

    #[test]
    fn mappings_round_trip_wire_names_to_core_ids() {
        let names = mappings(&["fs.list", "mcp:tool", "get_time"]).unwrap();

        assert_eq!(names.get("fs_list"), Some(&"fs.list".to_string()));
        assert_eq!(names.get("mcp_tool"), Some(&"mcp:tool".to_string()));
        assert_eq!(names.get("get_time"), Some(&"get_time".to_string()));
    }

    #[test]
    fn mappings_rejects_collisions_between_distinct_core_ids() {
        assert!(mappings(&["fs.list", "fs_list"]).is_err());
    }

    #[test]
    fn mappings_accepts_duplicate_core_ids() {
        assert!(mappings(&["get_time", "get_time"]).is_ok());
    }
}

